 inp=out/f"negative-{room['id']}-input.json";dest=out/f"negative-{room['id']}.json";inp.write_text(json.dumps(q));c=subprocess.run(['node',str(R/'tools/native-all-cells.cjs'),str(inp),str(dest)]);assert c.returncode==1
 rows=[a for a in json.load(open(dest))['rows']if a['name'].startswith('spawn-0 ')and not a['name'].endswith(' return-to-arrival')];assert len(rows)==len(room['fixtureNegatives']);assert all(a['error']=='No path found'and a['final']==room['spawn']and a['bodyCollisionSamples']==0 for a in rows);negative+=rows
